window.listOfSelect=window.listOfSelect||[];function findSelect(inputId){return listOfSelect.find(select=>select.id==="roro-wrapper-"+inputId)}window.roroAddOption=function(inputId,label,value,categoryLabel=null){const select=findSelect(inputId);select&&select.ready.then(()=>select.addOption(label,value,categoryLabel))},window.roroAddOptionsAjax=function(inputId,url,params={}){const select=findSelect(inputId);if(!select)return Promise.resolve([]);const query=new URLSearchParams(params).toString(),target=query?url+(url.includes("?")?"&":"?")+query:url;return Promise.all([select.ready,fetch(target,{headers:{Accept:"application/json"}}).then(r=>r.json())]).then(([,options])=>((options||[]).forEach(opt=>select.addOption(opt.label,opt.value,opt.category??null)),options||[]))},window.roroDisableSelect=function(inputId,disable=!0){const select=findSelect(inputId);select&&select.ready.then(()=>select.disable(disable))},window.roroReadonlySelect=function(inputId,readonly=!0){const select=findSelect(inputId);select&&select.ready.then(()=>select.readonly(readonly))},window.roroShowDropDown=function(inputId,show=!0){const select=findSelect(inputId);select&&select.ready.then(()=>select.showDropDown(show))},window.addSelect=function(elt){listOfSelect.push(new RoroSelect(elt.dataset.id,elt.dataset.value))},window.addMultiSelect=function(elt){let values=[];try{values=elt.dataset.values?JSON.parse(elt.dataset.values):[]}catch{values=[]}listOfSelect.push(new RoroMultiSelect(elt.dataset.id,elt.dataset.name,values))},RoroDom.ready(function(){RoroDom.qsa(".roro-wrapper-select").forEach(function(el){el.closest(".roro-repeatable-row")||addSelect(el)}),RoroDom.qsa(".roro-wrapper-multi-select").forEach(function(el){el.closest(".roro-repeatable-row")||addMultiSelect(el)})});
